import itertools

def is_kawaii(seq):
    unique_vals = set(seq)
    for k in unique_vals:
        if k >= 2:
            if k-1 not in unique_vals:
                return False
            # First occurrence of k-1
            first_k_minus_1 = seq.index(k-1)
            # Last occurrence of k
            last_k = len(seq) - 1 - seq[::-1].index(k)
            if first_k_minus_1 >= last_k:
                return False
    return True

def count_kawaii(n):
    count = 0
    # The max value in a kawaii sequence of length n is n.
    # We iterate through all sequences of length n with values in {1, ..., n}.
    for seq in itertools.product(range(1, n + 1), repeat=n):
        if is_kawaii(seq):
            count += 1
    return count

for n in range(1, 7):
    print(f"n={n}, count={count_kawaii(n)}")

import itertools

def is_kawaii_relative(seq):
    # seq is a sequence of ranks {1, 2, ..., M}
    unique_vals = set(seq)
    for k in unique_vals:
        if k >= 2:
            if k-1 not in unique_vals:
                return False
            first_k_minus_1 = seq.index(k-1)
            last_k = len(seq) - 1 - seq[::-1].index(k)
            if first_k_minus_1 >= last_k:
                return False
    return True

def count_kawaii_relative(n, m):
    count = 0
    for seq in itertools.product(range(1, m + 1), repeat=n):
        if is_kawaii_relative(seq):
            count += 1
    return count

for n in range(1, 6):
    for m in range(n, n+3):
        print(f"n={n}, m={m}, count={count_kawaii_relative(n, m)}")
